{-# LANGUAGE OverloadedStrings #-}
import Data.Aeson (object)
import Data.Either (isLeft)
import Data.Time (getCurrentTime)
import Shikigami.Agent.Name (mkAgentName)
import Shikigami.Agent.Principal (compatibilityIdentity)
import Shikigami.Agent.Run.Key (RunKey(..))
import Shikigami.Agent.RunJob (RunRouteKind(..),runJobWorkflowId)
import Shikigami.Trigger.Enqueue (addressedRunJob)
import Shikigami.RunJobs qualified as Jobs
main :: IO ()
main = do
 now <- getCurrentTime
 first <- either (fail . show) pure (mkAgentName "first")
 second <- either (fail . show) pure (mkAgentName "second")
 let job name key = addressedRunJob now (compatibilityIdentity name) name AgentWorkflowRoute (object []) (RunKey key)
 print ("distinct agents share caller-key workflow",runJobWorkflowId (job first "shared") == runJobWorkflowId (job second "shared"))
 print ("empty fresh key refuses its own queue decoder",isLeft (Jobs.decodeRunJob (Jobs.encodeRunJob (job first ""))))
